  padding: 0;
}
table.time-series-table th {
  padding: 0;
}
table.time-series-table th input{
  text-align: center;
}
.time-series-table td {
  padding: 0;
}
.time-series-table tr {
  padding: 0;
}
table.time-series-table input {
  width: fit-content;
}
td.time-series-data {
  border: 1px solid #ddd;
  background-color: rgb(233, 236, 239);
  text-align: right;
}
td.time-series-data span {
  color: '#2d5e77';
  border: None;
  background-color: inherit;
}
td.time-series-oor span {
  color: red;
}
